// n8n Code node - enforce correct metadata for webm recordings
for (const item of items) {
  if (item.binary?.audio0) {
    const b = item.binary.audio0;

    // Force consistent filename
    b.fileName = "recording.webm";

    // Force correct mimetype for webm
    b.mimeType = "audio/webm";
  }
}
return items;

/**
 * n8n Code node — Parse OpenAI "Message a model" output (new Responses shape)
 * Extracts: item.json.output[0].content[0].text
 * Returns: parsed note JSON at root, plus ok/meta helpers
 */

function extractJsonString(raw) {
  if (raw == null) return null;

  let s = String(raw).trim();

  // Remove ```json fences if present
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();

  // Try direct object extraction
  const firstBrace = s.indexOf("{");
  const lastBrace = s.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return s.slice(firstBrace, lastBrace + 1).trim();
  }

  // Try array extraction
  const firstBracket = s.indexOf("[");
  const lastBracket = s.lastIndexOf("]");
  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    return s.slice(firstBracket, lastBracket + 1).trim();
  }

  return null;
}

function safeJsonParseFromText(text) {
  const jsonStr = extractJsonString(text);
  if (!jsonStr) throw new Error("Could not locate JSON in model output text.");
  return JSON.parse(jsonStr);
}

return items.map((item) => {
  // ✅ This is the actual model text in your screenshot
  const text =
    item.json?.output?.[0]?.content?.[0]?.text ??
    item.json?.output?.[0]?.content?.find?.((c) => c?.type === "output_text")?.text ??
    item.json?.content ??
    item.json?.message?.content ??
    item.json?.text;

  try {
    const note = safeJsonParseFromText(text);

    return {
      json: {
        ok: true,
        ...note, // <-- IMPORTANT: put the note fields at the root for the UI
        meta: {
          ...(note.meta || {}),
          confidence_overall: note.meta?.confidence_overall || "",
        },
      },
    };
  } catch (e) {
    return {
      json: {
        ok: false,
        error: e.message,
        raw_preview: (text ? String(text).slice(0, 2000) : null),
      },
    };
  }
});

// Normalize webhook payload AND preserve binary (audio0)

return items.map((item) => {
  const j = item.json ?? {};
  const outerBody = j.body ?? {};

  let inner = null;

  // If body.body is a JSON string, parse it
  if (typeof outerBody.body === "string") {
    try {
      inner = JSON.parse(outerBody.body);
    } catch (e) {
      inner = null;
    }
  } else if (typeof outerBody.body === "object" && outerBody.body) {
    inner = outerBody.body;
  }

  // Build normalized payload
  const normalized = {
    ...j,
    body: {
      ...outerBody,
      ...(inner ?? {}),
    },
  };

  // Ensure transcript field exists consistently
  normalized.text =
    j.text ??
    normalized.body?.text ??
    normalized.body?.transcript ??
    normalized.body?.transcription ??
    "not_provided";

  // ✅ IMPORTANT: preserve binary (audio0, etc.)
  return {
    json: normalized,
    binary: item.binary, // keeps audio0 for Transcribe a recording
  };
});

// Iteramos por cada elemento que llega (normalmente es 1, pero n8n maneja arrays de items)
for (const item of $input.all()) {
  try {
    // Obtenemos el texto original que viene en 'patient_clinical_context'
    const contextString = item.json.body.patient_clinical_context;

    if (contextString) {
      // Parseamos el texto a un objeto JSON
      const patientData = JSON.parse(contextString);

      // Ahora asignamos TODOS los campos principales a nuevas variables en el item.json
      // para que sean fácilmente accesibles en los siguientes nodos.

      // -- Datos Generales del Paciente --
      item.json.patient_full_name = patientData.full_name;
      item.json.patient_first_name = patientData.first_name;
      item.json.patient_last_name = patientData.last_name;
      item.json.patient_dob = patientData.dob;
      item.json.patient_gender = patientData.gender;
      item.json.patient_phone = patientData.phone;
      item.json.patient_email = patientData.email;
      item.json.patient_ssn = patientData.ssn;
      item.json.patient_emr_id = patientData.emr_id;
      item.json.patient_address = patientData.address;
      item.json.patient_citizenship = patientData.citizenship;

      // -- Seguro y Coordinación --
      item.json.patient_case_manager = patientData.case_manager;
      item.json.patient_insurance_company = patientData.insurance_company;
      item.json.patient_diagnoses = patientData.diagnoses;
      item.json.patient_presenting_problems = patientData.presenting_problems;

      // -- Datos del PCP (Primary Care Physician) --
      item.json.patient_pcp_name = patientData.pcp_name;
      item.json.patient_pcp_phone = patientData.pcp_phone;
      item.json.patient_pcp_address = patientData.pcp_address;
      item.json.patient_pcp_conditions = patientData.pcp_conditions;
      item.json.patient_pcp_medications = patientData.pcp_medications;

      // -- Datos Psiquiátricos --
      item.json.patient_psych_name = patientData.psych_name;
      item.json.patient_psych_phone = patientData.psych_phone;
      item.json.patient_psych_address = patientData.psych_address;
      item.json.patient_psych_conditions = patientData.psych_conditions;
      item.json.patient_psych_medications = patientData.psych_medications;

      // -- Datos de Farmacia --
      item.json.patient_pharmacy_name = patientData.pharmacy_name;
      item.json.patient_pharmacy_phone = patientData.pharmacy_phone;
      item.json.patient_pharmacy_fax = patientData.pharmacy_fax;
      item.json.patient_pharmacy_address = patientData.pharmacy_address;

      // Opcional: También puedes guardar todo el objeto parseado directamente si quieres
      item.json.patient_full_object = patientData;
    }

  } catch (error) {
    // Si hay un error al parsear el JSON, imprimimos el error pero no rompemos el flujo
    console.error("Error parseando patient_clinical_context:", error.message);
    item.json.parsing_error = error.message;
  }
}

// Retornamos el item modificado a n8n
return $input.all();
